"""Four additional independently authored test answers."""
import json
from pathlib import Path
ANSWERS=[
('2028/D','Process card types in increasing order. For each player keep the reachable earlier card with maximum preference value. Card i is reachable precisely if one such maximum exceeds that player preference for i. Record the predecessor/player, then update all three maxima if reachable. Reconstruct the path to n by predecessors. Edges always increase the card type, so this is DAG reachability with sufficient summarized predecessors. O(n) time and space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;vector<vector<int>>p(3,vector<int>(n));for(auto&r:p)for(int&x:r)cin>>x;vector<int>pre(n,-1),who(n);int best[3]={0,0,0};for(int i=1;i<n;i++){for(int j=0;j<3;j++)if(p[j][best[j]]>p[j][i]){pre[i]=best[j];who[i]=j;break;}if(pre[i]!=-1)for(int j=0;j<3;j++)if(p[j][i]>p[j][best[j]])best[j]=i;}if(pre[n-1]==-1){cout<<"NO\n";continue;}vector<pair<int,int>>path;for(int v=n-1;v;v=pre[v])path.push_back({who[v],v+1});reverse(path.begin(),path.end());cout<<"YES\n"<<path.size()<<'\n';string names="qkj";for(auto x:path)cout<<names[x.first]<<' '<<x.second<<'\n';}}'''),
('2028/E','Root at 1 and compute h[u], the shortest downward distance to a non-root leaf. Leaves have probability zero. At an internal non-root vertex Alice optimally chooses its parent (larger probability), and the Queen chooses the child with smallest h. Induction gives child probability = parent probability*h/(h+1). For the minimum-height child this yields min child probability=u_probability*(h[u]-1)/h[u]; the fair-coin equation gives u_probability=parent_probability*h[u]/(h[u]+1). These values satisfy the max/min Bellman equations and boundary conditions, with strict descent toward a leaf, proving optimality. Compute iteratively, using modular inverses. O(n) time and space.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;const ll MOD=998244353;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;vector<vector<int>>g(n);for(int i=1,u,v;i<n;i++){cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}vector<int>par(n,-1),order{0},h(n,n);for(int i=0;i<(int)order.size();i++){int u=order[i];for(int v:g[u])if(v!=par[u]){par[v]=u;order.push_back(v);}}for(int i=n-1;i>0;i--){int u=order[i];if(g[u].size()==1)h[u]=0;h[par[u]]=min(h[par[u]],h[u]+1);}vector<ll>inv(n+2),ans(n);inv[1]=1;for(int i=2;i<=n+1;i++)inv[i]=MOD-(MOD/i)*inv[MOD%i]%MOD;ans[0]=1;for(int i=1;i<n;i++){int u=order[i];ans[u]=ans[par[u]]*h[u]%MOD*inv[h[u]+1]%MOD;}for(int i=0;i<n;i++)cout<<ans[i]<<(i+1==n?'\n':' ');}}'''),
('2019/A','Fix one chosen red index i. At most ceil((i-1)/2) nonadjacent vertices can be chosen strictly before its left neighbor, and similarly after its right neighbor, giving total 1+floor(i/2)+floor((n-i-1)/2) in zero-based indexing. Maximize a[i]+that count over i. For an optimum choose i attaining its maximum red value: this is an upper bound and is attained by taking alternating positions on each remaining path. O(n) time, O(1) extra space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n;cin>>n;int ans=0;for(int i=0,x;i<n;i++){cin>>x;ans=max(ans,x+1+i/2+(n-i-1)/2);}cout<<ans<<'\n';}}'''),
('2019/B','At x[i] (zero-based), covering segments count (i+1)*(n-i)-1; every segment chooses one endpoint no larger and one no smaller, excluding the degenerate pair. At each integer strictly between x[i] and x[i+1] the count is (i+1)*(n-i-1). Add the corresponding point/gap lengths into a map indexed by coverage, then answer queries by lookup. O((n+q)log n) time, O(n) space; use 64-bit integers.',r'''#include <bits/stdc++.h>
using namespace std;using ll=long long;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,q;cin>>n>>q;vector<ll>x(n);for(auto&v:x)cin>>v;map<ll,ll>cnt;for(int i=0;i<n;i++){cnt[1LL*(i+1)*(n-i)-1]++;if(i+1<n)cnt[1LL*(i+1)*(n-i-1)]+=x[i+1]-x[i]-1;}while(q--){ll k;cin>>k;auto it=cnt.find(k);cout<<(it==cnt.end()?0:it->second)<<(q?' ':'\n');}}}''')]
if __name__=='__main__':
    p=Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
